: 15px 0;\n        padding: 10px;\n        background-color: #f1f1f1;\n        border-left: 5px solid #4CAF50;\n        border-radius: 5px;\n        line-height: 1.6;\n    }\n\n    b {\n        color: #ff5722;\n    }\n\n    @media (max-width: 600px) {\n        ul li {\n            font-size: 14px;\n            margin: 5px 0; /* 减少手机端的上下间隔 */\n            padding: 8px;  /* 减少手机端的内部填充 */\n        }\n    }\n</style>',NULL),('partner','143240035',NULL),('payCode','0',NULL),('payType','leave',NULL),('pcurl','https://img.xxt.one/i/2025/1739150618.webp',NULL),('pc_view','lxf_mb',NULL),('peurl','https://img.xxt.one/i/2025/1739542862.webp',NULL),('platform_public_key','',NULL),('priceType','3',NULL),('qd_code','1',NULL),('qd_val','1-10',NULL),('qqpay','0',NULL),('redis_code','0',NULL),('redis_db','0',NULL),('redis_host','',NULL),('redis_pass','',NULL),('redis_port','',NULL),('register','0',NULL),('script','\n<script>\n    // 创建雪花飘落效果\n    const createSnowflake = () => {\n        const snowflake = document.createElement(\'div\');\n        snowflake.className = \'snowflake\';\n        snowflake.style.left = Math.random() * window.innerWidth + \'px\';\n        snowflake.style.animationDuration = Math.random() * 3 + 2 + \'s\';\n        document.body.appendChild(snowflake);\n\n        // 移除雪花\n        setTimeout(() => {\n            snowflake.remove();\n        }, 5000);\n    };\n\n    // 每隔一段时间生成雪花\n    setInterval(createSnowflake, 300);\n\n    // 添加CSS样式\n    const style = document.createElement(\'style\');\n    style.textContent = `\n        .snowflake {\n            position: absolute;\n            top: -10px;\n            width: 10px;\n            height: 10px;\n            background-color: white;\n            opacity: 0.8;\n            border-radius: 50%;\n            animation: fall linear infinite;\n        }\n        @keyframes fall {\n            to {\n                transform: translateY(100vh);\n            }\n        }\n        .trail {\n            position: absolute;\n            width: 8px;\n            height: 8px;\n            background-color: rgba(255, 0, 0, 0.5);\n            border-radius: 50%;\n            pointer-events: none;\n            transition: transform 0.5s, opacity 0.5s;\n            opacity: 0.6;\n        }\n    `;\n    document.head.appendChild(style);\n</script>',NULL),('session','6',NULL),('sort','ASC',NULL),('str_date','',NULL),('sub_domain','',NULL),('sub_domain_prefix','',NULL),('sub_grade','2',NULL),('sub_price','5',NULL),('sub_price_code','1',NULL),('sub_user_percent','0',NULL),('successUrl','/?mod=order',NULL),('title','小正网课系统',NULL),('token','23456789.',NULL),('topDocs','<span style=\"color: red;\">\n  ①人工客服微信：Xzstudio2024<br>\n  ②下单前请务必详细阅读商品介绍及相关注意事项，确保了解产品详情。<br>\n  ③如未能查询到课程，请尝试多次查询，或确认账号密码是否正确。若仍无法查询，请联系客服。\n所有网课售后时间均为30天\n</span>',NULL),('tx_fee','5',NULL),('tx_money','10',NULL),('type_money','0',NULL),('userAlert','这里是用户后台公告',NULL),('userInviteAlert','',NULL),('userLoginAlert','这里是用户登录公告',NULL),('user_code','1',NULL),('us_pc_view','default',NULL),('us_view','default',NULL),('view','lxf_mb',NULL),('visit','1',NULL),('weihu','0',NULL),('weihu_msg','网站正在维修 急单联系微信客服',NULL),('wk_add','add',NULL),('wk_budan','budan',NULL),('wk_chadan','chadan',NULL),('wk_get','get',NULL),('wk_getclass','getclass',NULL),('wxpay','1',NULL),('wxqq','1',NULL),('wx_push','1',NULL),('wx_push_url','https://push.showdoc.com.cn/server/api/push/87cabb16d43d827a205a84ef68c2951a1022219528',NULL),('zhuzhan','xxtjy.cn',NULL);
