INSERT INTO `sky_goods` VALUES (61,1,'学习通（全包）',2768,'3','默认学习时间为早6晚11，其余时间暂停学习。除作业、讨论外全包。测验正确率低于70%不交卷。学习次数不占分会赠送视频总时长的15%左右。考试只考1个，若需要考试多门请在考完后点补刷。每次补刷会考一门。','',1,0,1,1,0,0,'','https://s2.loli.net/2024/08/03/vKuaLrzU7Ij9fV6.jpg'),(62,1,'学习通（任务点）',2769,'2','自建满分题库已包含cet-4 cet-6 上海市安全教育，其余专业课题库均采用万能题库覆盖，目前已实现全题型支持。只含视频+测验','',1,0,1,1,0,0,'','https://s2.loli.net/2024/08/03/vKuaLrzU7Ij9fV6.jpg'),(63,1,'学习通（单考试）',2770,'2','默认5分钟交卷。默认不重考考试。该考试无视考试剩余时间，无视人脸识别，无视考前承诺书，无视App限制。若考试中含有主观题则不打开试卷。若题库数量低于65%则不交卷。','',1,0,1,1,0,0,'','https://s2.loli.net/2024/08/03/vKuaLrzU7Ij9fV6.jpg'),(64,1,'学习通（作业|按科）',2775,'2.5','将课程里的所有作业一次性全部完成。单选、多选、判断题型包满分。该项目不会自动重考未满分的试卷。','',1,0,1,1,0,0,'','https://s2.loli.net/2024/08/03/vKuaLrzU7Ij9fV6.jpg'),(65,1,'学习通（作业|按个）',3150,'2','该项目会查到账号下的所有作业，并显示所属课程。注意，已完成的作业也会被查到。单选、多选、判断题型包满分。其余题型不包！ 若作业已经完成，且分数不为100，且无主观题，且可以重考，满足以上条件则会自动重考作业并作答。','',1,0,1,1,0,0,'','https://s2.loli.net/2024/08/03/vKuaLrzU7Ij9fV6.jpg'),(66,1,'智慧树(快)',8400,'4','包视频,作业,互动(自行研究得分规则),见面课,考试,持续一比一看视频直到结束','',1,0,2,1,0,0,'','https://s2.loli.net/2024/11/08/WLtnv94duB5M1C8.png'),(67,1,'智慧树(慢)',8402,'4','包视频,作业,互动(自行研究得分规则),见面课,考试,一比一看视频,每天固定学习30分钟 ','',1,0,2,1,0,0,'','https://s2.loli.net/2024/11/08/WLtnv94duB5M1C8.png'),(68,1,'小沐_U校园整本',9671,'5','默认满分 ,时长25小时，真实填充答案非改分！！！限时开放单元会自动补刷 , 可控分控时长 ,格式：分数|时长 账号 密码 ,时长的单位是小时，例如 98|50 账号 密码 表示整本 98分，总时长 50 小时。','',1,0,5,1,0,0,'','https://s2.loli.net/2024/11/08/ZJM9HcvdtkaKDYx.png'),(69,1,'小沐_U校园AI整本',9672,'5','可控分（建议填95,85,75,...），可控时长≤5h\r\n所有任务可设置作答日期，当前未开放的任务选中默认开放时自动补刷\r\n❗教材：必修选修都刷，但选修不计成绩；时长等30min后更新； ❗单元因小节均分控分将上下浮动1~5分（建议不满分时使用） ❗可能会出现进度100%，时长足够，但分数延迟更新的情况','',1,0,5,1,0,0,'','https://s2.loli.net/2024/11/08/ZJM9HcvdtkaKDYx.png'),(70,1,'智慧树/AI课程（全包-慢 ）',2780,'4','全包，官方题库，视频平均分配到互动分每天完成。特价0.01-- [2025-05-01结束]','',1,0,2,1,0,0,'','https://s2.loli.net/2024/11/08/WLtnv94duB5M1C8.png'),(71,1,'智慧树/AI课程（全包-秒 ）',2781,'4','全包，官方题库，秒刷后补习惯分。特价0.01-- [2025-05-01结束]','',1,0,2,1,0,0,'','https://s2.loli.net/2024/11/08/WLtnv94duB5M1C8.png'),(72,1,'智慧树/AI课程（考试）',2782,'2','官方题库，包满分，十分钟左右完成 特价0.01-- [2025-05-01结束]','',1,0,2,1,0,0,'','https://s2.loli.net/2024/11/08/WLtnv94duB5M1C8.png'),(73,1,'无售后_学习通(包考)',9516,'1.5','【包含课件，章测，考试，闯关带锁及人脸可过，6~7点逐批上号，晚10~11逐批次下号，模拟真人作息，考试环节在答案填充完毕后会等5分钟左右再提交。】 PS：项目在2025.1.1日后引入了AI大模型，提高了误下必修课的答题容错率，但请勿完全依赖此模型。<货源端: 选修课无脑下 基本都是95+ >','',1,0,7,1,0,0,'','https://s2.loli.net/2024/08/03/vKuaLrzU7Ij9fV6.jpg'),(74,1,'无售后_学习通(不包考)',9517,'1','【包含课件，章测，考试，闯关带锁及人脸可过，6~7点逐批上号，晚10~11逐批次下号，模拟真人作息，考试环节在答案填充完毕后会等5分钟左右再提交。】 PS：项目在2025.1.1日后引入了AI大模型，提高了误下必修课的答题容错率，但请勿完全依赖此模型。<货源端: 选修课无脑下 基本都是95+ >','',1,0,7,1,0,0,'','https://s2.loli.net/2024/08/03/vKuaLrzU7Ij9fV6.jpg'),(75,1,'中国大学-慕课号-自动更新',6361,'3','全包，秒单，讨论自动复制前一个，支持新版考试，主观','',1,0,6,1,0,0,'','https://s2.loli.net/2024/11/08/fN3p7EGMVl9KdSD.jpg');
